#include <cstdint>
#include <cstdio>
#include "gb2312_font.hpp"
#include "esp_heap_caps.h"

/* Auto-generated GB2312 16x16 font interface, 8178 slots (含空洞), from simhei.ttf
 * 点阵数据在 TF 卡 /font/gb2312_16.bin（由 tools/font_to_bin.py 生成），
 * 启动时经 gb2312_font_load() 读入 PSRAM；unicode 映射表仍编译在固件内。 */

static uint8_t* s_font_ram = nullptr;   /* PSRAM: 8178 x 32 B */

bool gb2312_font_load(const char* path) {
    if (s_font_ram) return true;        /* 已加载，幂等 */
    if (!path) return false;
    FILE* f = fopen(path, "rb");
    if (!f) return false;
    uint8_t* ram = static_cast<uint8_t*>(
        heap_caps_malloc(8178 * 32, MALLOC_CAP_SPIRAM | MALLOC_CAP_8BIT));
    if (!ram) { fclose(f); return false; }
    size_t n = fread(ram, 1, 8178 * 32, f);
    fclose(f);
    if (n != 8178 * 32) { heap_caps_free(ram); return false; }
    s_font_ram = ram;
    return true;
}

bool gb2312_font_ready(void) {
    return s_font_ram != nullptr;
}

