int gb2312_index(uint32_t unicode) {
  int lo = 0, hi = 7445 - 1;
  while (lo <= hi) {
    int mid = (lo + hi) / 2;
    if (GB2312_MAP[mid].unicode == unicode) return GB2312_MAP[mid].gb_index;
    if (GB2312_MAP[mid].unicode < unicode) lo = mid + 1; else hi = mid - 1;
  }
  return -1;
}

const uint8_t* gb2312_glyph(int gb_index) {
  if (gb_index < 0 || gb_index >= 8178 || !s_font_ram) return nullptr;
  return s_font_ram + gb_index * 32;
}